    pub fn nested_view_model_selection_by_property_name(
        &self,
        property_name: &str,
    ) -> Option<(usize, Option<usize>)> {
        let property_index = self.property_index_by_name(property_name)?;
        let view_model = self
            .view_models
            .iter()
            .find(|view_model| view_model.property_index == property_index)?;
        let view_model_index = view_model.referenced_view_model_index?;
        let instance_index = match view_model.endpoint.value() {
            RuntimeViewModelPointer::OwnedGenerated { .. } => None,
            RuntimeViewModelPointer::Imported { object_id } => Some(
                view_model
                    .view_model_instance_ids
                    .iter()
                    .position(|id| *id == object_id)?,
            ),
            RuntimeViewModelPointer::Null
            | RuntimeViewModelPointer::DataContextRoot
            | RuntimeViewModelPointer::Retained { .. } => {
                return None;
            }
        };
        Some((view_model_index, instance_index))
    }

    pub(crate) fn instance_identity(&self) -> u64 {
        self.instance_identity
    }

    pub(crate) fn allocation_identity(&self) -> u64 {
        self.allocation_identity
    }

    /// Last registered numeric value for one C++ `SymbolType` value.
    ///
    /// `ViewModelInstance::addValue` walks concrete value occurrences and
    /// overwrites the symbol table, so duplicate symbols are resolved by
    /// value creation order rather than by property name.
    pub(crate) fn number_cell_for_symbol(
        &self,
        file: &RuntimeFile,
        symbol_type: u8,
    ) -> Option<RuntimeViewModelCell> {
        let view_model = file.view_model(self.view_model_index)?;
        self.value_order.iter().rev().find_map(|occurrence| {
            if occurrence.kind != RuntimeOwnedViewModelValueKind::Number {
                return None;
            }
            let property = view_model.properties.get(occurrence.property_index)?;
            if property.uint_property("symbolTypeValue") != Some(u64::from(symbol_type)) {
                return None;
            }
            self.numbers
                .get(occurrence.slot_index)
                .map(|number| number.cell.clone())
        })
    }

    // Distinguishes separately-created owned instances. C++
    // Artboard::bindViewModelInstance rebinds unconditionally; Rust keeps an
    // explicit allocation-independent identity for compatibility entrypoints.
    fn next_instance_identity() -> u64 {
        use std::sync::atomic::{AtomicU64, Ordering};
        static NEXT: AtomicU64 = AtomicU64::new(0);
        NEXT.fetch_add(1, Ordering::Relaxed)
    }

    fn next_allocation_identity() -> u64 {
        use std::sync::atomic::{AtomicU64, Ordering};
        static NEXT: AtomicU64 = AtomicU64::new(1);
        NEXT.fetch_add(1, Ordering::Relaxed)
    }

    fn mark_structurally_mutated(&mut self) {
        RuntimeOwnedViewModelParentRelay::rebind_dependents(&self.parent_relay);
    }

    fn bind_structural_ownership(&mut self) {
        bind_owned_view_model_list_parent_relays(&mut self.lists, &self.parent_relay);
        bind_owned_view_model_child_parent_relays(&mut self.view_models, &self.parent_relay);
    }

    fn detach_list_storage_unbound(&mut self) {
        let parent_relay = Rc::clone(&self.parent_relay);
        detach_owned_view_model_list_storage(&mut self.lists, &parent_relay);
        detach_owned_view_model_child_list_storage(&mut self.view_models, &parent_relay);
    }

    /// Advance the values stored directly in this instance and in embedded
    /// view-model properties. C++ `ViewModelInstance::advanced()` also walks
    /// list items; those are shared `Rc` instances in Rust, so they are
    /// returned for recursion after this `RefCell` borrow is released.
    pub(crate) fn advance_script_frame_local(
        &mut self,
    ) -> (bool, Vec<Rc<RefCell<RuntimeOwnedViewModelInstance>>>) {
        let mut shared_children = Vec::new();
        let mut changed = false;
        for occurrence in self.value_order.clone() {
            match occurrence.kind {
                RuntimeOwnedViewModelValueKind::Trigger => {
                    if let Some(trigger) = self.triggers.get_mut(occurrence.slot_index) {
                        changed |= reset_runtime_owned_triggers(std::slice::from_mut(trigger));
                    }
                }
                RuntimeOwnedViewModelValueKind::List => {
                    if let Some(list) = self.lists.get(occurrence.slot_index) {
                        collect_runtime_owned_list_children(
                            std::slice::from_ref(list),
                            &mut shared_children,
                        );
                    }
                }
                RuntimeOwnedViewModelValueKind::ViewModel => {
                    if let Some(view_model) = self.view_models.get_mut(occurrence.slot_index) {
                        changed |= view_model.advance_script_frame(&mut shared_children);
                    }
                }
                _ => {}
            }
        }
        (changed, shared_children)
    }

    pub(crate) fn advanced_data_context(&mut self) {
        for occurrence in self.value_order.clone() {
            match occurrence.kind {
                RuntimeOwnedViewModelValueKind::Trigger => {
                    if let Some(trigger) = self.triggers.get(occurrence.slot_index) {
                        trigger.advanced();
                    }
                }
                RuntimeOwnedViewModelValueKind::List => {
                    if let Some(list) = self.lists.get(occurrence.slot_index) {
                        advance_runtime_owned_list_children(std::slice::from_ref(list));
                    }
                }
                RuntimeOwnedViewModelValueKind::ViewModel => {
                    if let Some(view_model) = self.view_models.get_mut(occurrence.slot_index) {
                        view_model.advanced_data_context();
                    }
                }
                _ => {}
            }
        }
    }

    pub fn new(file: &RuntimeFile, view_model_index: usize) -> Option<Self> {
        let mut instance = Self::from_view_model_unbound(file, view_model_index, None)?;
        Self::complete_generated_view_model_links(&mut instance)?;
        Some(instance)
    }

    /// Complete the retained ViewModel-valued property graph created for a
    /// generated instance.
    ///
    /// Pinned C++ `File::createViewModelInstance` recursively creates a
    /// concrete `ViewModelInstance` for every ViewModel-valued property and
    /// installs it as that property's `referenceViewModelInstance`
    /// (`src/file.cpp:1141-1200`). Keep the same concrete identity here so
    /// scripting and DataContext consumers retain the selected child itself
    /// instead of reconstructing a scoped projection of the outer root.
    fn complete_generated_view_model_links(instance: &mut Self) -> Option<()> {
        for child in &mut instance.view_models {
            if !matches!(
                child.endpoint.value(),
                RuntimeViewModelPointer::OwnedGenerated { .. }
            ) {
                continue;
            }
            let mut linked = child.materialize_active_instance_unbound()?;
            Self::complete_generated_view_model_links(&mut linked)?;
            child
                .endpoint
                .set_linked_instance_silent(Some(Rc::new(RefCell::new(linked))));
        }
        instance.bind_structural_ownership();
        Some(())
    }

    /// Clone and complete one authored instance exactly like C++
    /// `ViewModelRuntime::createInstanceFromIndex`: nested ViewModel and list
    /// references become retained mutable instances, and one source-instance
    /// map preserves aliases across both kinds of edge.
    ///
    /// Reference: rive-runtime `d788e8ec6e8b598526607d6a1e8818e8b637b60c`,
    /// `src/viewmodel/runtime/viewmodel_runtime.cpp:124-133` and
    /// `src/file.cpp:898-983`.
    pub fn from_instance(
        file: &RuntimeFile,
        view_model_index: usize,
        instance_index: usize,
    ) -> Option<Self> {
        let mut instance = Self::from_imported_instance(file, view_model_index, instance_index)?;
        Self::complete_imported_view_model_links(&mut instance, &mut BTreeMap::new())?;
        Some(instance)
    }

    /// Named counterpart to [`Self::from_instance`], matching C++
    /// `ViewModelRuntime::createInstanceFromName` at rive-runtime
    /// `d788e8ec6e8b598526607d6a1e8818e8b637b60c`,
    /// `src/viewmodel/runtime/viewmodel_runtime.cpp:145-154`.
    pub fn from_instance_name(
        file: &RuntimeFile,
        view_model_index: usize,
        instance_name: &str,
    ) -> Option<Self> {
        let reference = file.view_model_instance_named(view_model_index, instance_name)?;
        Self::from_instance(file, view_model_index, reference.instance_index)
    }

    fn from_imported_instance(
        file: &RuntimeFile,
        view_model_index: usize,
        instance_index: usize,
    ) -> Option<Self> {
        let view_model = file.view_model(view_model_index)?;
        let instance = view_model.instances.into_iter().nth(instance_index)?;
        Self::from_view_model(file, view_model_index, Some(instance.object))
    }

    fn complete_imported_view_model_links(
        instance: &mut Self,
        instances_map: &mut BTreeMap<u32, Rc<RefCell<Self>>>,
    ) -> Option<()> {
        for child in &mut instance.view_models {
            let RuntimeViewModelPointer::Imported { object_id } = child.endpoint.value() else {
                continue;
            };
            let linked = if let Some(linked) = instances_map.get(&object_id) {
                Rc::clone(linked)
            } else {
                let active = child.materialize_active_instance()?;
                let linked = Rc::new(RefCell::new(active));
                instances_map.insert(object_id, Rc::clone(&linked));
                {
                    let mut linked_instance = linked.try_borrow_mut().ok()?;
                    Self::complete_imported_view_model_links(&mut linked_instance, instances_map)?;
                }
                linked
            };
            child.endpoint.set_linked_instance_silent(Some(linked));
        }

        let parent_relay = Rc::clone(&instance.parent_relay);
        for list in &mut instance.lists {
            let (item_count, source_items) = {
                let value = list.value.borrow();
                let items = value
                    .items
                    .iter()
                    .map(|item| {
                        (
                            item.occurrence_identity,
                            item.authored_source_object_id,
                            Rc::clone(&item.instance),
                            item.parent_registered,
                        )
                    })
                    .collect::<Vec<_>>();
                (value.item_count, items)
            };
            let mut items = Vec::with_capacity(source_items.len());
            for (occurrence_identity, source_object_id, source_instance, parent_registered) in
                source_items
            {
                let linked = if let Some(source_object_id) = source_object_id {
                    if let Some(linked) = instances_map.get(&source_object_id) {
                        Rc::clone(linked)
                    } else {
                        instances_map.insert(source_object_id, Rc::clone(&source_instance));
                        {
                            let mut linked_instance = source_instance.try_borrow_mut().ok()?;
                            Self::complete_imported_view_model_links(
                                &mut linked_instance,
                                instances_map,
                            )?;
                        }
                        source_instance
                    }
                } else {
                    source_instance
                };
                let child_relay = Rc::clone(&linked.try_borrow().ok()?.parent_relay);
                let mut item = RuntimeOwnedViewModelListItem {
                    occurrence_identity,
                    instance: linked,
                    authored_source_object_id: source_object_id,
                    child_relay,
                    parent_registered: false,
                };
                if parent_registered {
                    item.attach_parent(&parent_relay);
                }
                items.push(item);
            }
            list.value = Rc::new(RefCell::new(RuntimeOwnedViewModelListValue {
                parent_relay: Rc::downgrade(&parent_relay),
                item_count,
                items,
            }));
            list.cell = RuntimeViewModelCell::new(RuntimeViewModelCellValue::List);
        }
        instance.bind_structural_ownership();
        Some(())
    }

    pub(crate) fn from_instance_object(
        file: &RuntimeFile,
        view_model_index: usize,
        instance: &RuntimeObject,
    ) -> Option<Self> {
        Self::from_view_model(file, view_model_index, Some(instance))
    }

    fn from_view_model(
        file: &RuntimeFile,
        view_model_index: usize,
        instance: Option<&RuntimeObject>,
    ) -> Option<Self> {
        let mut instance = Self::from_view_model_unbound(file, view_model_index, instance)?;
        instance.bind_structural_ownership();
        Some(instance)
    }

    fn from_view_model_unbound(
        file: &RuntimeFile,
        view_model_index: usize,
        instance: Option<&RuntimeObject>,
    ) -> Option<Self> {
        file.view_model(view_model_index)?;
        let use_generated_defaults = instance.is_none();
        let parent_path = [view_model_index];
        let numbers = instance
            .map(|instance| {
                runtime_owned_view_model_numbers_for_instance(file, view_model_index, instance)
            })
            .unwrap_or_else(|| runtime_owned_view_model_numbers(file, view_model_index));
        let booleans = instance
            .map(|instance| {
                runtime_owned_view_model_booleans_for_instance(file, view_model_index, instance)
            })
            .unwrap_or_else(|| runtime_owned_view_model_booleans(file, view_model_index));
        let strings = instance
            .map(|instance| {
                runtime_owned_view_model_strings_for_instance(file, view_model_index, instance)
            })
            .unwrap_or_else(|| runtime_owned_view_model_strings(file, view_model_index));
        let colors = instance
            .map(|instance| {
                runtime_owned_view_model_colors_for_instance(file, view_model_index, instance)
            })
            .unwrap_or_else(|| runtime_owned_view_model_colors(file, view_model_index));
        let enums = instance
            .map(|instance| {
                runtime_owned_view_model_enums_for_instance(file, view_model_index, instance)
            })
            .unwrap_or_else(|| runtime_owned_view_model_enums(file, view_model_index));
        let symbol_list_indices = instance
            .map(|instance| {
                runtime_owned_view_model_symbol_list_indices_for_instance(
                    file,
                    view_model_index,
                    instance,
                )
            })
            .unwrap_or_else(|| {
                runtime_owned_view_model_symbol_list_indices(file, view_model_index)
            });
        let lists = instance
            .map(|instance| {
                runtime_owned_view_model_lists_for_instance(file, view_model_index, instance)
            })
            .unwrap_or_else(|| runtime_owned_view_model_lists(file, view_model_index));
        let assets = instance
            .map(|instance| {
                runtime_owned_view_model_assets_for_instance(file, view_model_index, instance)
            })
            .unwrap_or_else(|| runtime_owned_view_model_assets(file, view_model_index));
        let font_assets = instance
            .map(|instance| {
                runtime_owned_view_model_font_assets_for_instance(file, view_model_index, instance)
            })
            .unwrap_or_else(|| runtime_owned_view_model_font_assets(file, view_model_index));
        let blob_assets = instance
            .map(|instance| {
                runtime_owned_view_model_blob_assets_for_instance(file, view_model_index, instance)
            })
            .unwrap_or_else(|| runtime_owned_view_model_blob_assets(file, view_model_index));
        let artboards = instance
            .map(|instance| {
                runtime_owned_view_model_artboards_for_instance(file, view_model_index, instance)
            })
            .unwrap_or_else(|| runtime_owned_view_model_artboards(file, view_model_index));
        let triggers = instance
            .map(|instance| {
                runtime_owned_view_model_triggers_for_instance(file, view_model_index, instance)
            })
            .unwrap_or_else(|| runtime_owned_view_model_triggers(file, view_model_index));
        let view_models = runtime_owned_view_model_property_children(
            file,
            view_model_index,
            instance,
            &parent_path,
            &[view_model_index],
            use_generated_defaults,
        );
        let parent_relay = RuntimeOwnedViewModelParentRelay::new();
        let value_order = runtime_owned_view_model_value_order(file, view_model_index, instance);
        let item_index_symbol_slot = symbol_list_indices.len().checked_sub(1);
        let instance = Self {
            view_model_index,
            name: instance
                .and_then(|instance| instance.string_property("name"))
                .unwrap_or_default()
                .to_owned(),
            instance_identity: Self::next_instance_identity(),
            allocation_identity: Self::next_allocation_identity(),
            parent_relay,
            property_names: runtime_owned_view_model_property_names(file, view_model_index),
            numbers,
            booleans,
            strings,
            colors,
            enums,
            symbol_list_indices,
            lists,
            assets,
            font_assets,
            blob_assets,
            artboards,
            triggers,
            view_models,
            value_order,
            item_index_symbol_slot,
        };
        Some(instance)
    }

    pub(crate) fn property_index_by_name(&self, property_name: &str) -> Option<usize> {
        runtime_owned_view_model_property_index_by_name(&self.property_names, property_name)
    }

    pub(crate) fn name(&self) -> &str {
        &self.name
    }

    /// Removes the first retained value for an authored property index.
    ///
    /// This is the safe-Rust counterpart of pinned C++
    /// `ViewModelInstance::removeValue`: the schema/name table remains intact,
    /// while the concrete value occurrence disappears. Nested ViewModel
    /// references detach their parent edge before the retained endpoint is
    /// released.
    pub fn remove_value_by_property_index(&mut self, property_index: usize) -> bool {
        let Some(order_index) = self
            .value_order
            .iter()
            .position(|occurrence| occurrence.property_index == property_index)
        else {
            return false;
        };
        let occurrence = self.value_order.remove(order_index);
        macro_rules! remove_slot {
            ($values:expr) => {{
                $values.remove(occurrence.slot_index);
            }};
        }
        match occurrence.kind {
            RuntimeOwnedViewModelValueKind::Number => remove_slot!(self.numbers),
            RuntimeOwnedViewModelValueKind::Boolean => remove_slot!(self.booleans),
            RuntimeOwnedViewModelValueKind::String => remove_slot!(self.strings),
            RuntimeOwnedViewModelValueKind::Color => remove_slot!(self.colors),
            RuntimeOwnedViewModelValueKind::Enum => remove_slot!(self.enums),
            RuntimeOwnedViewModelValueKind::SymbolListIndex => {
                remove_slot!(self.symbol_list_indices);
                self.item_index_symbol_slot = match self.item_index_symbol_slot {
                    Some(winner) if winner == occurrence.slot_index => None,
                    Some(winner) if winner > occurrence.slot_index => Some(winner - 1),
                    winner => winner,
                };
            }
            RuntimeOwnedViewModelValueKind::List => remove_slot!(self.lists),
            RuntimeOwnedViewModelValueKind::Asset => remove_slot!(self.assets),
            RuntimeOwnedViewModelValueKind::FontAsset => remove_slot!(self.font_assets),
            RuntimeOwnedViewModelValueKind::BlobAsset => remove_slot!(self.blob_assets),
            RuntimeOwnedViewModelValueKind::Artboard => remove_slot!(self.artboards),
            RuntimeOwnedViewModelValueKind::Trigger => remove_slot!(self.triggers),
            RuntimeOwnedViewModelValueKind::ViewModel => {
                if let Some(linked) = self.view_models[occurrence.slot_index]
                    .endpoint
                    .linked_instance()
                {
                    let child_relay = Rc::clone(&linked.borrow().parent_relay);
                    RuntimeOwnedViewModelParentRelay::remove_parent(
                        &child_relay,
                        &self.parent_relay,
                    );
                }
                remove_slot!(self.view_models);
            }
        }
        for later in &mut self.value_order {
            if later.kind == occurrence.kind && later.slot_index > occurrence.slot_index {
                later.slot_index -= 1;
            }
        }
        true
    }

    fn mutate_linked_by_property_names(
        &mut self,
        property_path: &[&str],
        mutation: impl FnOnce(&mut RuntimeOwnedViewModelInstance, &[&str]) -> bool,
    ) -> Option<bool> {
        if property_path.len() < 2 {
            return None;
        }
        let property_index = self.property_index_by_name(property_path[0])?;
        let linked = self
            .view_models
            .iter()
            .find(|property| property.property_index == property_index)?
            .endpoint
            .linked_instance()?;
        Some({
            let Ok(mut linked_instance) = linked.try_borrow_mut() else {
                return Some(false);
            };
            mutation(&mut linked_instance, &property_path[1..])
        })
    }

    fn mutate_linked_by_property_path(
        &mut self,
        property_path: &[usize],
        mutation: impl FnOnce(&mut RuntimeOwnedViewModelInstance, &[usize]) -> bool,
    ) -> Option<bool> {
        if property_path.len() < 2 {
            return None;
        }
        let property_index = property_path[0];
        let linked = self
            .view_models
            .iter()
            .find(|property| property.property_index == property_index)?
            .endpoint
            .linked_instance()?;
        Some({
            let Ok(mut linked_instance) = linked.try_borrow_mut() else {
                return Some(false);
            };
            mutation(&mut linked_instance, &property_path[1..])
        })
    }

    pub fn set_number_by_property_index(&mut self, property_index: usize, value: f32) -> bool {
        let Some(number) = self
            .numbers
            .iter_mut()
            .find(|number| number.property_index == property_index)
        else {
            return false;
        };
        if !number.set_value(value) {
            return false;
        }
        true
    }

    /// Write a number through a previously resolved dense numeric-value slot.
    ///
    /// This is the direct hot-path counterpart to
    /// [`Self::number_slot_by_property_index`]. It performs no allocation or
    /// schema/name lookup.
    pub fn set_number_by_slot(&mut self, number_slot: usize, value: f32) -> bool {
        let Some(number) = self.numbers.get_mut(number_slot) else {
            return false;
        };
        if !number.set_value(value) {
            return false;
        }
        true
    }

    pub fn set_number_by_property_name(&mut self, property_name: &str, value: f32) -> bool {
        let Some(property_index) = self.property_index_by_name(property_name) else {
            return false;
        };
        self.set_number_by_property_index(property_index, value)
    }

    pub fn number_source_handle_by_property_name(
        &self,
        property_name: &str,
    ) -> Option<RuntimeOwnedViewModelNumberSourceHandle> {
        let property_index = self.property_index_by_name(property_name)?;
        self.numbers
            .iter()
            .any(|number| number.property_index == property_index)
            .then_some(RuntimeOwnedViewModelNumberSourceHandle {
                property_path: vec![property_index],
            })
    }

    pub fn number_source_handle_by_property_name_path(
        &self,
        property_path: &str,
    ) -> Option<RuntimeOwnedViewModelNumberSourceHandle> {
        let property_path = property_path.split('/').collect::<Vec<_>>();
        if property_path.is_empty() || property_path.iter().any(|segment| segment.is_empty()) {
            return None;
        }
        let property_path = self.number_property_path_by_names(&property_path)?;
        Some(RuntimeOwnedViewModelNumberSourceHandle { property_path })
    }

    pub fn set_number_by_source_handle(
        &mut self,
        handle: &RuntimeOwnedViewModelNumberSourceHandle,
        value: f32,
    ) -> bool {
        self.set_number_by_property_path(&handle.property_path, value)
    }

    pub fn set_number_by_property_name_path(&mut self, property_path: &str, value: f32) -> bool {
        let property_path = property_path.split('/').collect::<Vec<_>>();
        if property_path.is_empty() || property_path.iter().any(|segment| segment.is_empty()) {
            return false;
        }
        self.set_number_by_property_names(&property_path, value)
    }

    pub fn set_number_by_property_names(&mut self, property_path: &[&str], value: f32) -> bool {
        if let Some(changed) = self
            .mutate_linked_by_property_names(property_path, |linked, path| {
                linked.set_number_by_property_names(path, value)
            })
        {
            return changed;
        }
        if property_path.len() == 1 {
            return self.set_number_by_property_name(property_path[0], value);
        }
        let Some((number_name, view_model_path)) = property_path.split_last() else {
            return false;
        };
        let Some(view_model) = self.view_model_by_property_names_mut(view_model_path) else {
            return false;
        };
        if !matches!(
            view_model.endpoint.value(),
            RuntimeViewModelPointer::OwnedGenerated { .. }
        ) {
            return false;
        }
        let changed = view_model.set_number_by_property_name(number_name, value);
        changed
    }

    pub(crate) fn set_number_by_property_path(
        &mut self,
        property_path: &[usize],
        value: f32,
    ) -> bool {
        if let Some(changed) = self.mutate_linked_by_property_path(property_path, |linked, path| {
            linked.set_number_by_property_path(path, value)
        }) {
            return changed;
        }
        if property_path.len() == 1 {
            return self.set_number_by_property_index(property_path[0], value);
        }
        let Some((number_index, view_model_path)) = property_path.split_last() else {
            return false;
        };
        let Some(view_model) = self.view_model_by_property_path_mut(view_model_path) else {
            return false;
        };
        if !matches!(
            view_model.endpoint.value(),
            RuntimeViewModelPointer::OwnedGenerated { .. }
        ) {
            return false;
        }
        let changed = view_model.set_number_by_property_index(*number_index, value);
        changed
    }

    fn number_property_path_by_names(&self, property_path: &[&str]) -> Option<Vec<usize>> {
        if property_path.len() == 1 {
            let property_index = self.property_index_by_name(property_path[0])?;
            return self
                .numbers
                .iter()
                .any(|number| number.property_index == property_index)
                .then_some(vec![property_index]);
        }

        let (number_name, view_model_names) = property_path.split_last()?;
        let (view_model_path, view_model) =
            self.view_model_property_path_by_names(view_model_names)?;
        let property_index = view_model.property_index_by_name(number_name)?;
        if view_model
            .active_number_value_by_property_index(property_index)
            .is_none()
        {
            return None;
        }
        let mut property_path = view_model_path;
        property_path.push(property_index);
        Some(property_path)
    }

