    /// The retained property cell at one top-level property index.
    fn scalar_cell_by_property_index(&self, property_index: usize) -> Option<RuntimeViewModelCell> {
        let occurrence = self
            .value_order
            .iter()
            .find(|occurrence| occurrence.property_index == property_index)?;
        Some(match occurrence.kind {
            RuntimeOwnedViewModelValueKind::Number => {
                self.numbers.get(occurrence.slot_index)?.cell.clone()
            }
            RuntimeOwnedViewModelValueKind::Boolean => {
                self.booleans.get(occurrence.slot_index)?.cell.clone()
            }
            RuntimeOwnedViewModelValueKind::String => {
                self.strings.get(occurrence.slot_index)?.cell.clone()
            }
            RuntimeOwnedViewModelValueKind::Color => {
                self.colors.get(occurrence.slot_index)?.cell.clone()
            }
            RuntimeOwnedViewModelValueKind::Enum => {
                self.enums.get(occurrence.slot_index)?.cell.clone()
            }
            RuntimeOwnedViewModelValueKind::SymbolListIndex => self
                .symbol_list_indices
                .get(occurrence.slot_index)?
                .cell
                .clone(),
            RuntimeOwnedViewModelValueKind::List => {
                self.lists.get(occurrence.slot_index)?.cell.clone()
            }
            RuntimeOwnedViewModelValueKind::Asset => {
                self.assets.get(occurrence.slot_index)?.cell.clone()
            }
            RuntimeOwnedViewModelValueKind::FontAsset => {
                self.font_assets.get(occurrence.slot_index)?.cell.clone()
            }
            RuntimeOwnedViewModelValueKind::BlobAsset => {
                self.blob_assets.get(occurrence.slot_index)?.cell.clone()
            }
            RuntimeOwnedViewModelValueKind::Artboard => {
                self.artboards.get(occurrence.slot_index)?.cell.clone()
            }
            RuntimeOwnedViewModelValueKind::Trigger => {
                self.triggers.get(occurrence.slot_index)?.cell.clone()
            }
            RuntimeOwnedViewModelValueKind::ViewModel => {
                self.view_models.get(occurrence.slot_index)?.endpoint.cell()
            }
        })
    }

    /// Walk a resolved property path to the retained property cell:
    /// intermediate segments walk the SHARED child slots exactly like the
    /// `*_value_by_property_path` readers, the final segment must land on a
    /// property slot. This is C++ `DataContext::tryGetViewModelProperty`'s
    /// loop returning the retained `ViewModelInstanceValue`, not a copy.
    pub(crate) fn cell_by_property_path(
        &self,
        property_path: &[usize],
    ) -> Option<RuntimeViewModelCell> {
        if property_path.len() == 1 {
            return self.scalar_cell_by_property_index(property_path[0]);
        }
        let (view_model_index, rest) = property_path.split_first()?;
        self.view_models
            .iter()
            .find(|view_model| view_model.property_index == *view_model_index)?
            .active_scalar_cell_by_property_path(rest)
    }

    fn cell_by_relative_scoped_property_path(
        &self,
        context_path: &[usize],
        property_path: &[usize],
    ) -> Option<RuntimeViewModelCell> {
        if context_path.is_empty() {
            return self.cell_by_property_path(property_path);
        }
        let (view_model_index, rest) = context_path.split_first()?;
        self.view_models
            .iter()
            .find(|view_model| view_model.property_index == *view_model_index)?
            .active_scalar_cell_by_scoped_property_path(rest, property_path)
    }

    /// Resolve a listener condition relative to one compatibility context
    /// path without building a temporary combined path. The context path must
    /// land on the listener's declared view model; the listener property path
    /// then walks that retained instance to its scalar cell.
    pub(crate) fn cell_by_scoped_property_path(
        &self,
        context_path: &[usize],
        view_model_index: usize,
        property_path: &[usize],
    ) -> Option<RuntimeViewModelCell> {
        if self.view_model_index_by_property_path(context_path)? != view_model_index {
            return None;
        }
        if context_path.is_empty() {
            return self.cell_by_property_path(property_path);
        }
        self.cell_by_relative_scoped_property_path(context_path, property_path)
    }

    /// C++ `DataContext::tryGetViewModelProperty` against this instance's own
    /// storage: `path[0]` must name this instance's view model, the tail is
    /// the property walk. Returns the retained cell by shared identity.
    pub fn cell_for_source_path(&self, path: &[u32]) -> Option<RuntimeViewModelCell> {
        if path.len() < 2 || usize::try_from(path[0]).ok()? != self.view_model_index {
            return None;
        }
        let property_path = path[1..]
            .iter()
            .map(|&segment| usize::try_from(segment).ok())
            .collect::<Option<Vec<_>>>()?;
        self.cell_by_property_path(&property_path)
    }

    /// Resolve an absolute authored source path against one instance in a
    /// compatibility context chain. The first source segment names the view
    /// model at `context_path`; the remaining segments walk that retained
    /// instance to the exact property cell.
    pub(crate) fn cell_for_scoped_source_path(
        &self,
        context_path: &[usize],
        path: &[u32],
    ) -> Option<RuntimeViewModelCell> {
        let (&view_model_index, property_path) = path.split_first()?;
        if property_path.is_empty() {
            return None;
        }
        let view_model_index = usize::try_from(view_model_index).ok()?;
        let property_path = property_path
            .iter()
            .map(|&segment| usize::try_from(segment).ok())
            .collect::<Option<Vec<_>>>()?;
        self.cell_by_scoped_property_path(context_path, view_model_index, &property_path)
    }

    pub(crate) fn relative_cell_by_context_name_hash_path(
        &self,
        context_path: &[usize],
        source_path: &[u32],
    ) -> Result<Option<RuntimeViewModelCell>, RuntimeProjectNameAmbiguity> {
        if source_path.is_empty() {
            return Ok(None);
        }
        let mut property_path = context_path.to_vec();
        for name_hash in source_path {
            let property_names = if property_path.is_empty() {
                self.property_names.as_slice()
            } else {
                let Some(view_model) = self.view_model_by_property_path(&property_path) else {
                    return Ok(None);
                };
                view_model.property_names.as_slice()
            };
            let Some(property_index) =
                runtime_owned_view_model_property_index_by_project_name_hash(
                    property_names,
                    *name_hash,
                )?
            else {
                return Ok(None);
            };
            property_path.push(property_index);
        }
        Ok(self
            .cell_by_property_path(&property_path)
            .filter(|cell| matches!(cell.value(), RuntimeViewModelCellValue::Number(_))))
    }

    pub(crate) fn relative_cell_by_context_name_path(
        &self,
        context_path: &[usize],
        source_path: &[String],
    ) -> Result<Option<RuntimeViewModelCell>, RuntimeProjectNameAmbiguity> {
        if source_path.is_empty() {
            return Ok(None);
        }
        let mut property_path = context_path.to_vec();
        for property_name in source_path {
            let property_names = if property_path.is_empty() {
                self.property_names.as_slice()
            } else {
                let Some(view_model) = self.view_model_by_property_path(&property_path) else {
                    return Ok(None);
                };
                view_model.property_names.as_slice()
            };
            let Some(property_index) = runtime_owned_view_model_property_index_by_project_name(
                property_names,
                property_name,
            )?
            else {
                return Ok(None);
            };
            property_path.push(property_index);
        }
        Ok(self
            .cell_by_property_path(&property_path)
            .filter(|cell| matches!(cell.value(), RuntimeViewModelCellValue::Number(_))))
    }

